1	/**
2	 * The Sentry JavaScript SDK v8 migration for an Angular application's tracing
3	 * setup.
4	 *
5	 * Version 8 of the SDK folded the separate `@sentry/tracing` package into the
6	 * framework SDKs and replaced the integration classes with factory functions.
7	 * Three shapes an Angular workspace written against version 6 or 7 carries stop
8	 * resolving, and each one is defined by the SDK rather than by any application:
9	 *
10	 * - `@sentry/tracing` no longer exists as a package, so the `Integrations`
11	 *   object (and the `BrowserTracing` class it carried) cannot be imported at
12	 *   all. `@sentry/angular` 8 exports its own Angular-flavoured
13	 *   `browserTracingIntegration`, and that factory is the successor.
14	 * - `routingInstrumentation` was removed from the SDK. The Angular browser
15	 *   tracing integration performs the routing instrumentation itself, so the
16	 *   option the era code passed has no counterpart and no replacement value: it
17	 *   is folded into the factory call by disappearing from it.
18	 * - `tracingOrigins` was removed from the integration and has no counterpart
19	 *   there either. Its successor, `tracePropagationTargets`, is a top-level
20	 *   `Sentry.init` option, so the value has to move up one level rather than be
21	 *   dropped — dropping it would silently stop propagating trace headers to the
22	 *   very origins the application named.
23	 *
24	 * ```ts
25	 * import * as Sentry from '@sentry/angular';
26	 * import { Integrations } from '@sentry/tracing';
27	 *
28	 * Sentry.init({                              Sentry.init({
29	 *   integrations: [                            integrations: [
30	 *     new Integrations.BrowserTracing({          Sentry.browserTracingIntegration()
31	 *       tracingOrigins: ORIGINS,        ->     ],
32	 *       routingInstrumentation:                tracesSampleRate: 1.0,
33	 *         Sentry.routingInstrumentation        tracePropagationTargets: ORIGINS
34	 *     })                                     });
35	 *   ],
36	 *   tracesSampleRate: 1.0
37	 * });
38	 * ```
39	 *
40	 * Everything rides the parsed module's resolved bindings. The construction is
41	 * found by following the local binding `@sentry/tracing` exported, so an
42	 * `Integrations` imported from anywhere else is untouched and an aliased import
43	 * is still rewritten; the `init` call the option relocates into, and the
44	 * `routingInstrumentation` value that is dropped, both have to resolve to the
45	 * same Sentry SDK module the factory is being taken from.
46	 *
47	 * A construction this capability cannot fully account for is left exactly as it
48	 * is and reported — never half-edited. That is the whole point of the
49	 * relocation refusals: a `tracingOrigins` this capability cannot place is a
50	 * `tracingOrigins` it must not remove, because the resulting file would compile
51	 * and quietly trace nothing.
52	 */
53	
54	import { analyze } from 'yuku-analyzer';
55	import { compareStrings } from './angular-target-cell.ts';
56	
57	/** The SDK the successor factory is taken from. */
58	export const SENTRY_ANGULAR_MODULE = '@sentry/angular';
59	
60	/** The package v8 folded into the SDKs; it has no successor of its own. */
61	export const REMOVED_SENTRY_TRACING_MODULE = '@sentry/tracing';
62	
63	/** The removed integration container, and the removed class it carried. */
64	export const REMOVED_INTEGRATIONS_OBJECT = 'Integrations';
65	export const REMOVED_BROWSER_TRACING_CLASS = 'BrowserTracing';
66	
67	/** The v8 factory that replaced the class. */
68	export const BROWSER_TRACING_FACTORY = 'browserTracingIntegration';
69	
70	/** The SDK entry point the relocated option belongs to. */
71	export const SENTRY_INIT = 'init';
72	
73	/** The removed routing hook the v8 integration performs for itself. */
74	export const REMOVED_ROUTING_INSTRUMENTATION = 'routingInstrumentation';
75	
76	/** The removed integration option, and the init option it moves to. */
77	export const REMOVED_TRACING_ORIGINS_OPTION = 'tracingOrigins';
78	export const TRACE_PROPAGATION_TARGETS_OPTION = 'tracePropagationTargets';
79	
80	export type SentryV8Change = Readonly<{
81		kind: 'sentry-browser-tracing-integration' | 'sentry-trace-propagation-targets';
82		line: number;
83		from: string;
84		to: string;
85	}>;
86	
87	export type SentryV8Migration = Readonly<{
88		path: string;
89		source: string;
90		changed: boolean;
91		changes: readonly SentryV8Change[];
92		unhandled: readonly string[];
93	}>;
94	
95	type SemanticModule = ReturnType<typeof analyze>;
96	type AstNode = NonNullable<ReturnType<SemanticModule['parentOf']>>;
97	type ImportRecord = SemanticModule['imports'][number];
98	type BindingSymbol = NonNullable<ImportRecord['local']>;
99	
100	type Edit = Readonly<{ start: number; end: number; text: string }>;
101	
102	function lineOf(source: string, offset: number): number {
103		return source.slice(0, offset).split('\n').length;
104	}
105	
106	/** The leading whitespace of the line `offset` sits on. */
107	function indentAt(source: string, offset: number): string {
108		const lineStart = source.lastIndexOf('\n', offset - 1) + 1;
109		let cursor = lineStart;
110		while (cursor < offset) {
111			const character = source[cursor];
112			if (character !== ' ' && character !== '\t') break;
113			cursor += 1;
114		}
115		return source.slice(lineStart, cursor);
116	}
117	
118	/** Apply non-overlapping edits to a string, rightmost first. */
119	function applyEdits(text: string, edits: readonly Edit[]): string {
120		let result = text;
121		for (const edit of [...edits].sort((left, right) => right.start - left.start))
122			result = `${result.slice(0, edit.start)}${edit.text}${result.slice(edit.end)}`;
123		return result;
124	}
125	
126	/**
127	 * One module's import surface for a single package: the namespace binding if it
128	 * has one, the named bindings by exported name, and the declarations they came
129	 * from. A default binding is recorded only as `wide`, because a member reached
130	 * through one cannot be resolved by name.
131	 */
132	type ModuleImports = Readonly<{
133		present: boolean;
134		namespace: BindingSymbol | null;
135		named: ReadonlyMap<string, BindingSymbol>;
136		declarations: readonly AstNode[];
137		wide: boolean;
138	}>;
139	
140	function readModuleImports(module: SemanticModule, specifier: string): ModuleImports {
141		const named = new Map<string, BindingSymbol>();
142		const declarations: AstNode[] = [];
143		let namespace: BindingSymbol | null = null;
144		let present = false;
145		let wide = false;
146		for (const record of module.imports) {
147			if (record.specifier !== specifier) continue;
148			present = true;
149			const declaration = importDeclarationOf(module, record.node);
150			if (declaration !== null && !declarations.includes(declaration))
151				declarations.push(declaration);
152			const local = record.local;
153			if (local === null) continue;
154			if (record.isNamespace) {
155				namespace ??= local;
156				wide = true;
157				continue;
158			}
159			if (record.name === null || record.name === 'default') {
160				wide = true;
161				continue;
162			}
163			if (!named.has(record.name)) named.set(record.name, local);
164		}
165		return Object.freeze({
166			present,
167			namespace,
168			named,
169			declarations: Object.freeze(declarations),
170			wide,
171		});
172	}
173	
174	function importDeclarationOf(module: SemanticModule, node: AstNode): AstNode | null {
175		let current: AstNode | null = node;
176		while (current !== null) {
177			if (current.type === 'ImportDeclaration') return current;
178			current = module.parentOf(current);
179		}
180		return null;
181	}
182	
183	function namedSpecifiersOf(declaration: AstNode): readonly AstNode[] {
184		if (declaration.type !== 'ImportDeclaration') return [];
185		return declaration.specifiers.filter((specifier) => specifier.type === 'ImportSpecifier');
186	}
187	
188	function hasWideSpecifier(declaration: AstNode): boolean {
189		if (declaration.type !== 'ImportDeclaration') return false;
190		return declaration.specifiers.some((specifier) => specifier.type !== 'ImportSpecifier');
191	}
192	
193	/**
194	 * Whether `node` denotes `exportName` of the Sentry SDK: either the local of a
195	 * named import of it, or a static member of the SDK's namespace binding. Any
196	 * other expression — a member of some other object, a computed access, a
197	 * locally defined function of the same name — is not, and the caller refuses
198	 * rather than guesses.
199	 */
200	function isSdkExport(
201		module: SemanticModule,
202		node: AstNode,
203		sdk: ModuleImports,
204		exportName: string,
205	): boolean {
206		if (node.type === 'Identifier') {
207			const expected = sdk.named.get(exportName);
208			return expected !== undefined && module.symbolOf(node) === expected;
209		}
210		if (node.type !== 'MemberExpression' || node.computed || node.optional) return false;
211		const { object, property } = node;
212		if (property.type !== 'Identifier' || property.name !== exportName) return false;
213		if (object.type !== 'Identifier' || sdk.namespace === null) return false;
214		return module.symbolOf(object) === sdk.namespace;
215	}
216	
217	type PlainProperty = Readonly<{ node: AstNode; name: string; value: AstNode }>;
218	
219	/**
220	 * The properties of an object literal, when every one of them is a plain,
221	 * statically named, non-computed data property. A literal carrying a spread, a
222	 * computed key, a method, or an accessor returns null: this capability decides
223	 * both what an options literal contains and what it does not contain, and
224	 * neither question can be answered over a shape like that.
225	 */
226	function plainProperties(object: AstNode): readonly PlainProperty[] | null {
227		if (object.type !== 'ObjectExpression') return null;
228		const properties: PlainProperty[] = [];
229		for (const property of object.properties) {
230			if (property.type !== 'Property') return null;
231			if (property.kind !== 'init' || property.computed || property.method) return null;
232			const key = property.key;
233			const name =
234				key.type === 'Identifier'
235					? key.name
236					: key.type === 'Literal' && typeof key.value === 'string'
237						? key.value
238						: null;
239			if (name === null) return null;
240			properties.push(Object.freeze({ node: property, name, value: property.value }));
241		}
242		return Object.freeze(properties);
243	}
244	
245	/**
246	 * The options literal of the `Sentry.init` call that structurally encloses
247	 * `node`, or null when there is none the relocation can be trusted to. The walk
248	 * stops at the first enclosing init call: a construction nested inside one but
249	 * not inside its options literal is not a relocation target, it is a refusal.
250	 */
251	function enclosingInitOptions(
252		module: SemanticModule,
253		node: AstNode,
254		sdk: ModuleImports,
255	): AstNode | null {
256		let child = node;
257		let parent = module.parentOf(child);
258		while (parent !== null) {
259			if (
260				parent.type === 'CallExpression' &&
261				isSdkExport(module, parent.callee, sdk, SENTRY_INIT)
262			) {
263				const first = parent.arguments[0];
264				return first === child && child.type === 'ObjectExpression' ? child : null;
265			}
266			child = parent;
267			parent = module.parentOf(child);
268		}
269		return null;
270	}
271	
272	type Relocation = Readonly<{ target: AstNode; value: string; line: number }>;
273	
274	type Construction = Readonly<{
275		start: number;
276		end: number;
277		binding: BindingSymbol;
278		calleeText: string;
279		optionsText: string;
280		relocation: Relocation | null;
281		consumedRouting: boolean;
282	}>;
283	
284	/**
285	 * Rewrite the options literal of a removed `BrowserTracing` construction into
286	 * the argument its v8 factory takes: the two removed options are cut out and
287	 * everything else is carried through as it was written. When nothing survives,
288	 * the factory is called with no argument at all, which is what an integration
289	 * with no configuration is in v8.
290	 */
291	function rewriteOptions(
292		source: string,
293		object: AstNode,
294		properties: readonly PlainProperty[],
295		removed: ReadonlySet<PlainProperty>,
296	): string {
297		if (properties.every((property) => removed.has(property))) return '';
298		/**
299		 * Deletions are taken over maximal runs of adjacent removed properties, not
300		 * one property at a time. Two neighbours cut separately would each claim the
301		 * separator between them and the edits would overlap; a run claims it once.
302		 */
303		const deletions: Edit[] = [];
304		let index = 0;
305		while (index < properties.length) {
306			const first = properties[index];
307			if (first === undefined || !removed.has(first)) {
308				index += 1;
309				continue;
310			}
311			let lastIndex = index;
312			for (;;) {
313				const candidate = properties[lastIndex + 1];
314				if (candidate === undefined || !removed.has(candidate)) break;
315				lastIndex += 1;
316			}
317			const last = properties[lastIndex] ?? first;
318			const following = properties[lastIndex + 1];
319			const previous = properties[index - 1];
320			if (following !== undefined)
321				deletions.push({ start: first.node.start, end: following.node.start, text: '' });
322			else if (previous !== undefined) {
323				let end = last.node.end;
324				while (source[end] === ' ' || source[end] === '\t') end += 1;
325				if (source[end] === ',') end += 1;
326				deletions.push({ start: previous.node.end, end, text: '' });
327			}
328			index = lastIndex + 1;
329		}
330		const rebased = deletions.map((edit) => ({
331			start: edit.start - object.start,
332			end: edit.end - object.start,
333			text: edit.text,
334		}));
335		return applyEdits(source.slice(object.start, object.end), rebased);
336	}
337	
338	/**
339	 * Migrate one module's Sentry tracing setup onto the v8 SDK.
340	 *
341	 * A module that never imports `@sentry/tracing` is returned byte-identical. A
342	 * module that does not parse is a hard failure naming the file, never a silent
343	 * skip: a skipped file would be counted as unchanged, and the whole value of a
344	 * changeset is that an unchanged file really was unchanged.
345	 */
346	export function migrateSentryV8Tracing(path: string, source: string): SentryV8Migration {
347		const unchanged = (unhandled: readonly string[] = []): SentryV8Migration =>
348			Object.freeze({
349				path,
350				source,
351				changed: false,
352				changes: Object.freeze([]),
353				unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
354			});
355		if (!source.includes(REMOVED_SENTRY_TRACING_MODULE)) return unchanged();
356		const module = analyze(source, { path, lang: path.endsWith('.ts') ? 'ts' : 'js' });
357		const errors = module.diagnostics.filter((entry) => entry.severity === 'error');
358		if (errors.length > 0)
359			throw new Error(
360				`Sentry v8 migration: ${path} does not parse, so its removed ` +
361					`${REMOVED_SENTRY_TRACING_MODULE} constructions cannot be rewritten and it cannot be ` +
362					`honestly counted as unchanged. Diagnostics: ` +
363					errors.map((entry) => entry.message).join('; '),
364			);
365		const tracing = readModuleImports(module, REMOVED_SENTRY_TRACING_MODULE);
366		if (!tracing.present) return unchanged();
367		const unhandled: string[] = [];
368		if (tracing.wide)
369			unhandled.push(
370				`${path} imports ${REMOVED_SENTRY_TRACING_MODULE} as a namespace or default binding; a ` +
371					`${REMOVED_BROWSER_TRACING_CLASS} reached through one is not rewritten`,
372			);
373		for (const name of tracing.named.keys())
374			if (name !== REMOVED_INTEGRATIONS_OBJECT && name !== REMOVED_BROWSER_TRACING_CLASS)
375				unhandled.push(
376					`${path} imports ${name} from ${REMOVED_SENTRY_TRACING_MODULE}, a package v8 removed ` +
377						'with no successor for that export; the import was left in place',
378				);
379		const sites = constructionSites(module, tracing, path, unhandled);
380		if (sites.length === 0) return unchanged(unhandled);
381		const sdk = readModuleImports(module, SENTRY_ANGULAR_MODULE);
382		const factory = resolveFactoryReference(module, sdk);
383		if (factory === null) {
384			unhandled.push(
385				`${path} constructs ${REMOVED_SENTRY_TRACING_MODULE}'s ${REMOVED_BROWSER_TRACING_CLASS} ` +
386					`but no ${BROWSER_TRACING_FACTORY} could be established from ${SENTRY_ANGULAR_MODULE} ` +
387					'in this module; every construction was left whole',
388			);
389			return unchanged(unhandled);
390		}
391		const constructions = readConstructions(module, source, sites, sdk, path, unhandled);
392		const accepted = withoutContestedRelocations(constructions, path, unhandled);
393		if (accepted.length === 0) return unchanged(unhandled);
394		const edits: Edit[] = [];
395		const changes: SentryV8Change[] = [];
396		for (const construction of accepted) {
397			edits.push({
398				start: construction.start,
399				end: construction.end,
400				text: `${factory.reference}(${construction.optionsText})`,
401			});
402			changes.push({
403				kind: 'sentry-browser-tracing-integration',
404				line: lineOf(source, construction.start),
405				from: `new ${construction.calleeText}(…)`,
406				to: `${factory.reference}(${construction.optionsText === '' ? '' : '…'})`,
407			});
408			const relocation = construction.relocation;
409			if (relocation === null) continue;
410			const properties = plainProperties(relocation.target) ?? [];
411			const last = properties[properties.length - 1];
412			if (last === undefined) continue;
413			edits.push({
414				start: last.node.end,
415				end: last.node.end,
416				text: `,\n${indentAt(source, last.node.start)}${TRACE_PROPAGATION_TARGETS_OPTION}: ${relocation.value}`,
417			});
418			changes.push({
419				kind: 'sentry-trace-propagation-targets',
420				line: relocation.line,
421				from: `${REMOVED_TRACING_ORIGINS_OPTION}: ${relocation.value}`,
422				to: `${SENTRY_INIT} option ${TRACE_PROPAGATION_TARGETS_OPTION}: ${relocation.value}`,
423			});
424		}
425		edits.push(...factory.imports);
426		edits.push(...tracingImportEdits(module, source, tracing, accepted, path, unhandled));
427		unhandled.push(...unconsumedRoutingReports(module, sdk, accepted, path));
428		const migrated = applyEdits(source, edits);
429		return Object.freeze({
430			path,
431			source: migrated,
432			changed: migrated !== source,
433			changes: Object.freeze(
434				[...changes].sort(
435					(left, right) => left.line - right.line || compareStrings(left.from, right.from),
436				),
437			),
438			unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
439		});
440	}
441	
442	type Site = Readonly<{ node: AstNode; binding: BindingSymbol; calleeText: string }>;
443	
444	/**
445	 * Every `new BrowserTracing(...)` in the module, reached through a binding
446	 * `@sentry/tracing` exported. Both spellings the SDK offered are followed: the
447	 * class as a member of the `Integrations` object, and the class imported
448	 * directly. Any other use of either binding is reported rather than rewritten,
449	 * and its presence is what later keeps the import specifier in place.
450	 */
451	function constructionSites(
452		module: SemanticModule,
453		tracing: ModuleImports,
454		path: string,
455		unhandled: string[],
456	): readonly Site[] {
457		const sites: Site[] = [];
458		const integrations = tracing.named.get(REMOVED_INTEGRATIONS_OBJECT);
459		if (integrations !== undefined)
460			for (const reference of integrations.references) {
461				const member = module.parentOf(reference.node);
462				const isMember =
463					member !== null &&
464					member.type === 'MemberExpression' &&
465					!member.computed &&
466					member.object === reference.node &&
467					member.property.type === 'Identifier' &&
468					member.property.name === REMOVED_BROWSER_TRACING_CLASS;
469				const construction = isMember ? module.parentOf(member) : null;
470				if (
471					construction === null ||
472					construction.type !== 'NewExpression' ||
473					construction.callee !== member
474				) {
475					unhandled.push(
476						`${path}: ${integrations.name} from ${REMOVED_SENTRY_TRACING_MODULE} is used at ` +
477							`line ${lineOf(module.source, reference.node.start)} in a form other than ` +
478							`\`new ${integrations.name}.${REMOVED_BROWSER_TRACING_CLASS}(…)\`; it was left as it is`,
479					);
480					continue;
481				}
482				sites.push({
483					node: construction,
484					binding: integrations,
485					calleeText: module.source.slice(member.start, member.end),
486				});
487			}
488		const browserTracing = tracing.named.get(REMOVED_BROWSER_TRACING_CLASS);
489		if (browserTracing !== undefined)
490			for (const reference of browserTracing.references) {
491				const construction = module.parentOf(reference.node);
492				if (
493					construction === null ||
494					construction.type !== 'NewExpression' ||
495					construction.callee !== reference.node
496				) {
497					unhandled.push(
498						`${path}: ${browserTracing.name} from ${REMOVED_SENTRY_TRACING_MODULE} is used at ` +
499							`line ${lineOf(module.source, reference.node.start)} in a form other than ` +
500							`\`new ${browserTracing.name}(…)\`; it was left as it is`,
501					);
502					continue;
503				}
504				sites.push({
505					node: construction,
506					binding: browserTracing,
507					calleeText: reference.node.name,
508				});
509			}
510		return Object.freeze(sites);
511	}
512	
513	type FactoryReference = Readonly<{
514		reference: string;
515		/** The import edits naming the factory costs this module, if any. */
516		imports: readonly Edit[];
517	}>;
518	
519	/**
520	 * How this module will name the v8 factory. The SDK's namespace binding is
521	 * preferred because that is how an Angular entry point conventionally holds the
522	 * SDK; a named import of the factory is reused when one is already there; and a
523	 * module that imports the SDK by name gains one more specifier. A module that
524	 * does not import the SDK at all, or that already binds the factory's name to
525	 * something else, yields null and the caller refuses every construction: the
526	 * flavour of `browserTracingIntegration` matters, and this capability will not
527	 * invent an import to decide it.
528	 */
529	function resolveFactoryReference(
530		module: SemanticModule,
531		sdk: ModuleImports,
532	): FactoryReference | null {
533		const noEdits: readonly Edit[] = Object.freeze([]);
534		if (sdk.namespace !== null)
535			return Object.freeze({
536				reference: `${sdk.namespace.name}.${BROWSER_TRACING_FACTORY}`,
537				imports: noEdits,
538			});
539		const existing = sdk.named.get(BROWSER_TRACING_FACTORY);
540		if (existing !== undefined)
541			return Object.freeze({ reference: existing.name, imports: noEdits });
542		if (module.rootScope.find(BROWSER_TRACING_FACTORY) !== null) return null;
543		for (const declaration of sdk.declarations) {
544			const specifiers = namedSpecifiersOf(declaration);
545			const last = specifiers[specifiers.length - 1];
546			if (last === undefined) continue;
547			return Object.freeze({
548				reference: BROWSER_TRACING_FACTORY,
549				imports: Object.freeze([
550					{ start: last.end, end: last.end, text: `, ${BROWSER_TRACING_FACTORY}` },
551				]),
552			});
553		}
554		return null;
555	}
556	
557	function readConstructions(
558		module: SemanticModule,
559		source: string,
560		sites: readonly Site[],
561		sdk: ModuleImports,
562		path: string,
563		unhandled: string[],
564	): readonly Construction[] {
565		const constructions: Construction[] = [];
566		for (const site of sites) {
567			const node = site.node;
568			if (node.type !== 'NewExpression') continue;
569			const line = lineOf(source, node.start);
570			const refuse = (reason: string): void => {
571				unhandled.push(
572					`${path}: the ${REMOVED_BROWSER_TRACING_CLASS} construction at line ${line} ${reason}; ` +
573						'it was left exactly as it is',
574				);
575			};
576			if (node.arguments.length > 1) {
577				refuse(`takes more arguments than ${BROWSER_TRACING_FACTORY} accepts`);
578				continue;
579			}
580			const argument = node.arguments[0];
581			if (argument === undefined) {
582				constructions.push(
583					Object.freeze({
584						start: node.start,
585						end: node.end,
586						binding: site.binding,
587						calleeText: site.calleeText,
588						optionsText: '',
589						relocation: null,
590						consumedRouting: false,
591					}),
592				);
593				continue;
594			}
595			const properties = plainProperties(argument);
596			if (properties === null) {
597				refuse(
598					'is configured with something other than a plain object literal, so what it sets ' +
599						'cannot be established',
600				);
601				continue;
602			}
603			const removed = new Set<PlainProperty>();
604			let origins: PlainProperty | null = null;
605			let consumedRouting = false;
606			let refused = false;
607			for (const property of properties) {
608				if (property.name === REMOVED_TRACING_ORIGINS_OPTION) {
609					origins = property;
610					removed.add(property);
611					continue;
612				}
613				if (property.name === REMOVED_ROUTING_INSTRUMENTATION) {
614					if (!isSdkExport(module, property.value, sdk, REMOVED_ROUTING_INSTRUMENTATION)) {
615						refuse(
616							`passes a ${REMOVED_ROUTING_INSTRUMENTATION} this capability cannot resolve to ` +
617								`${SENTRY_ANGULAR_MODULE}'s own, which is the only one v8's integration ` +
618								'performs for itself',
619						);
620						refused = true;
621						break;
622					}
623					consumedRouting = true;
624					removed.add(property);
625				}
626			}
627			if (refused) continue;
628			let relocation: Relocation | null = null;
629			if (origins !== null) {
630				const target = enclosingInitOptions(module, node, sdk);
631				if (target === null) {
632					refuse(
633						`sets ${REMOVED_TRACING_ORIGINS_OPTION}, whose v8 successor ` +
634							`${TRACE_PROPAGATION_TARGETS_OPTION} is a ${SENTRY_INIT} option, but no ` +
635							`${SENTRY_ANGULAR_MODULE} ${SENTRY_INIT} options literal encloses it`,
636					);
637					continue;
638				}
639				const targetProperties = plainProperties(target);
640				if (targetProperties === null || targetProperties.length === 0) {
641					refuse(
642						`sets ${REMOVED_TRACING_ORIGINS_OPTION}, but the enclosing ${SENTRY_INIT} options ` +
643							`literal is not a plain object literal, so ${TRACE_PROPAGATION_TARGETS_OPTION} ` +
644							'cannot be established there',
645					);
646					continue;
647				}
648				if (targetProperties.some((entry) => entry.name === TRACE_PROPAGATION_TARGETS_OPTION)) {
649					refuse(
650						`sets ${REMOVED_TRACING_ORIGINS_OPTION}, but the enclosing ${SENTRY_INIT} call ` +
651							`already declares ${TRACE_PROPAGATION_TARGETS_OPTION}, and this capability will ` +
652							'not overwrite a value the application chose',
653					);
654					continue;
655				}
656				relocation = Object.freeze({
657					target,
658					value: source.slice(origins.value.start, origins.value.end),
659					line: lineOf(source, origins.node.start),
660				});
661			}
662			constructions.push(
663				Object.freeze({
664					start: node.start,
665					end: node.end,
666					binding: site.binding,
667					calleeText: site.calleeText,
668					optionsText: rewriteOptions(source, argument, properties, removed),
669					relocation,
670					consumedRouting,
671				}),
672			);
673		}
674		return Object.freeze(constructions);
675	}
676	
677	/**
678	 * Two constructions relocating into one `init` call would each claim the single
679	 * `tracePropagationTargets` option. There is no honest merge of two different
680	 * origin lists, so both are refused and left whole.
681	 */
682	function withoutContestedRelocations(
683		constructions: readonly Construction[],
684		path: string,
685		unhandled: string[],
686	): readonly Construction[] {
687		const claims = new Map<AstNode, number>();
688		for (const construction of constructions) {
689			const target = construction.relocation?.target;
690			if (target !== undefined) claims.set(target, (claims.get(target) ?? 0) + 1);
691		}
692		const kept: Construction[] = [];
693		for (const construction of constructions) {
694			const target = construction.relocation?.target;
695			if (target !== undefined && (claims.get(target) ?? 0) > 1) {
696				unhandled.push(
697					`${path}: the ${REMOVED_BROWSER_TRACING_CLASS} construction at line ` +
698						`${construction.relocation?.line ?? 0} shares its ${SENTRY_INIT} call with another ` +
699						`construction that also sets ${REMOVED_TRACING_ORIGINS_OPTION}; one ` +
700						`${TRACE_PROPAGATION_TARGETS_OPTION} cannot carry both, so both were left ` +
701						'exactly as they are',
702				);
703				continue;
704			}
705			kept.push(construction);
706		}
707		return Object.freeze(kept);
708	}
709	
710	/**
711	 * Drop the specifiers of `@sentry/tracing` whose every use this migration
712	 * rewrote, and the whole declaration when nothing of it is left. A declaration
713	 * that still binds something — a use this capability refused, an export it has
714	 * no successor for, a default binding — keeps its import, so the module names
715	 * what it still depends on instead of silently losing it.
716	 */
717	function tracingImportEdits(
718		module: SemanticModule,
719		source: string,
720		tracing: ModuleImports,
721		accepted: readonly Construction[],
722		path: string,
723		unhandled: string[],
724	): readonly Edit[] {
725		const consumed = new Map<BindingSymbol, number>();
726		for (const construction of accepted)
727			consumed.set(construction.binding, (consumed.get(construction.binding) ?? 0) + 1);
728		const retired = new Set<BindingSymbol>();
729		for (const [binding, count] of consumed)
730			if (count === binding.references.length) retired.add(binding);
731		const edits: Edit[] = [];
732		for (const declaration of tracing.declarations) {
733			const specifiers = namedSpecifiersOf(declaration);
734			if (specifiers.length === 0) continue;
735			if (hasWideSpecifier(declaration)) {
736				unhandled.push(
737					`${path} imports ${REMOVED_SENTRY_TRACING_MODULE} with a default or namespace binding ` +
738						'alongside named ones, so its import declaration was left as it is',
739				);
740				continue;
741			}
742			const kept = specifiers.filter((specifier) => {
743				const local =
744					specifier.type === 'ImportSpecifier' ? module.symbolOf(specifier.local) : null;
745				return local === null || !retired.has(local as BindingSymbol);
746			});
747			if (kept.length === specifiers.length) continue;
748			if (kept.length === 0) {
749				let end = declaration.end;
750				while (source[end] === ' ' || source[end] === '\t') end += 1;
751				if (source[end] === '\n') end += 1;
752				edits.push({ start: declaration.start, end, text: '' });
753				continue;
754			}
755			const first = specifiers[0] as AstNode;
756			const last = specifiers[specifiers.length - 1] as AstNode;
757			edits.push({
758				start: first.start,
759				end: last.end,
760				text: kept.map((specifier) => source.slice(specifier.start, specifier.end)).join(', '),
761			});
762		}
763		return Object.freeze(edits);
764	}
765	
766	/**
767	 * `routingInstrumentation` this migration did not consume. The export is gone
768	 * in v8 wherever it is reached from, so a reference left behind is a demand the
769	 * migrated module still makes and the reader is owed it by name.
770	 */
771	function unconsumedRoutingReports(
772		module: SemanticModule,
773		sdk: ModuleImports,
774		accepted: readonly Construction[],
775		path: string,
776	): readonly string[] {
777		const consumed = accepted.filter((construction) => construction.consumedRouting).length;
778		const references: number[] = [];
779		const named = sdk.named.get(REMOVED_ROUTING_INSTRUMENTATION);
780		if (named !== undefined)
781			for (const reference of named.references) references.push(reference.node.start);
782		if (sdk.namespace !== null)
783			for (const reference of sdk.namespace.references) {
784				const member = module.parentOf(reference.node);
785				if (
786					member !== null &&
787					member.type === 'MemberExpression' &&
788					!member.computed &&
789					member.property.type === 'Identifier' &&
790					member.property.name === REMOVED_ROUTING_INSTRUMENTATION
791				)
792					references.push(reference.node.start);
793			}
794		if (references.length <= consumed) return Object.freeze([]);
795		return Object.freeze([
796			`${path} still reaches ${SENTRY_ANGULAR_MODULE}'s ${REMOVED_ROUTING_INSTRUMENTATION}, which ` +
797				`v8 removed, at ${references.length - consumed} of ${references.length} use sites; only ` +
798				`the ones this migration folded into ${BROWSER_TRACING_FACTORY} were rewritten`,
799		]);
800	}
