31	export type WorkspaceFile = Readonly<{ path: string; source: string }>;
32	
33	export type AngularMigrationInput = Readonly<{
34		packageManifest: WorkspaceFile;
35		workspaceConfig: WorkspaceFile;
36		tsConfig: WorkspaceFile;
37		/** Application source modules, as read from the workspace. */
38		sourceModules: readonly WorkspaceFile[];
