83	function sha256(value: string): string {
84		return createHash('sha256').update(value).digest('hex');
85	}
86	
87	function describeConfigChange(change: ConfigChange): string {
88		if (change.to === null) return `removed ${change.path} (was ${change.from ?? 'absent'})`;
89		if (change.from === null) return `added ${change.path} = ${change.to}`;
90		return `${change.path}: ${change.from} -> ${change.to}`;
91	}
92	
93	function describeDependencyChange(change: DependencyChange): string {
94		const target = `${change.field}.${change.name}`;
95		return change.to === null
96			? `removed ${target} (was ${change.from}) — ${change.reason}`
97			: `${target}: ${change.from} -> ${change.to} — ${change.reason}`;
98	}
99	
100	function describeSourceChange(change: SourceChange | NgrxEffectChange | SentryV8Change): string {
101		return `line ${change.line}: ${change.kind} ${change.from} -> ${change.to}`;
102	}
103	
104	function file(
105		input: WorkspaceFile,
106		source: string,
107		kind: MigratedFile['kind'],
108		changes: readonly string[],
109	): MigratedFile {
110		return Object.freeze({
111			path: input.path,
112			kind,
113			changed: source !== input.source,
114			sha256Before: sha256(input.source),
115			sha256After: sha256(source),
116			source,
117			changes: Object.freeze([...changes]),
