119	}
120	
121	/**
122	 * Apply every capability of the adapter to one workspace.
123	 *
124	 * Order matters in exactly one place: the workspace migration decides which
125	 * builder targets cannot be carried, and the packages those targets released
126	 * are what the manifest alignment then removes. Nothing else is ordered, and no
127	 * capability reads a file it was not handed.
128	 */
129	export function migrateAngularCliEraWorkspace(
130		input: AngularMigrationInput,
131		cell: AngularTargetCell,
132	): AngularMigration {
133		const unhandled: string[] = [];
